<script setup lang="ts">
const props = defineProps<{ ev: any }>(); const toast = useToast()
const { data, refresh } = await useAsyncData(`promos-${props.ev.id}`, () => api<any[]>(`/api/manage/events/${props.ev.id}/promos`), { server: false })
const n = reactive({ code: '', kind: 'percent', value: 10, maxUses: undefined as number | undefined, maxPerUser: 1, startsAt: '', endsAt: '', categoryIds: [] as string[] })
async function add() { try { await api(`/api/manage/events/${props.ev.id}/promos`, { method: 'POST', body: { ...n, maxUses: n.maxUses || undefined, startsAt: n.startsAt ? new Date(n.startsAt).toISOString() : undefined, endsAt: n.endsAt ? new Date(n.endsAt).toISOString() : undefined } }); toast.ok('Code créé'); n.code = ''; refresh() } catch (e) { toast.err(errMsg(e)) } }
</script>
<template>
  <div class="grid gap-6 xl:grid-cols-[380px_1fr]">
    <form class="card space-y-3 p-5" @submit.prevent="add"><h2 class="text-lg font-bold">Nouveau code promo</h2><label class="block"><span class="label">Code</span><input v-model="n.code" required minlength="3" class="input uppercase" placeholder="EARLY20"></label>
      <div class="grid grid-cols-2 gap-3"><label class="block"><span class="label">Type</span><select v-model="n.kind" class="input"><option value="percent">Pourcentage</option><option value="fixed">Montant fixe</option></select></label><label class="block"><span class="label">Valeur {{ n.kind === 'percent' ? '(%)' : `(${ev.currency})` }}</span><input v-model.number="n.value" type="number" min="1" :max="n.kind === 'percent' ? 100 : undefined" class="input"></label><label class="block"><span class="label">Utilisations max.</span><input v-model.number="n.maxUses" type="number" min="1" class="input" placeholder="illimité"></label><label class="block"><span class="label">Par acheteur</span><input v-model.number="n.maxPerUser" type="number" min="1" class="input"></label><label class="block"><span class="label">Début</span><input v-model="n.startsAt" type="datetime-local" class="input"></label><label class="block"><span class="label">Fin</span><input v-model="n.endsAt" type="datetime-local" class="input"></label></div>
      <fieldset><legend class="label">Catégories éligibles</legend><label v-for="c in ev.categories" :key="c.id" class="flex min-h-[40px] items-center gap-2 text-sm"><input v-model="n.categoryIds" type="checkbox" :value="c.id" class="accent-[rgb(var(--c-a))]">{{ c.name }}</label><p class="hint">Aucune case cochée = toutes les catégories.</p></fieldset><button class="btn btn-primary w-full">Créer le code</button></form>
    <div class="card overflow-x-auto"><table class="w-full min-w-[520px]"><thead><tr><th class="th">Code</th><th class="th">Remise</th><th class="th">Utilisé</th><th class="th">Validité</th></tr></thead><tbody class="divide-y divide-line"><tr v-for="p in data" :key="p.id"><td class="td font-mono font-bold">{{ p.code }}</td><td class="td">{{ p.kind === 'percent' ? `${p.value} %` : money(p.value, ev.currency) }}</td><td class="td">{{ p.usedCount }}{{ p.maxUses ? ` / ${p.maxUses}` : '' }}</td><td class="td text-muted">{{ p.endsAt ? `jusqu’au ${fdate(p.endsAt, { dateStyle: 'short' })}` : 'sans limite' }}</td></tr><tr v-if="!data?.length"><td colspan="4" class="td text-center text-muted">Aucun code promo.</td></tr></tbody></table></div>
  </div>
</template>
